-- Prevent new or updated catalogue items from having zero stock.\n-- NOT VALID keeps legacy zero-stock rows readable while enforcing the rule\n-- for every new INSERT/UPDATE from this point forward.\nDO $$\nBEGIN\n  IF NOT EXISTS (\n    SELECT 1\n    FROM pg_constraint\n    WHERE conname = 'pecas_catalogo_estoque_positivo_check'\n      AND conrelid = 'public.pecas_catalogo'::regclass\n  ) THEN\n    ALTER TABLE public.pecas_catalogo\n      ADD CONSTRAINT pecas_catalogo_estoque_positivo_check\n      CHECK (estoque_atual >= 1) NOT VALID;\n  END IF;\nEND $$;\n\nNOTIFY pgrst, 'reload schema';\n